import{_ as a,o as r,c as i,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Discord-бот","description":"","frontmatter":{"pageId":"admins/discord","contentRevision":1},"headers":[],"relativePath":"ru/admins/discord.md","filePath":"ru/admins/discord.md"}'),o={name:"ru/admins/discord.md"};function d(s,e,n,l,c,p){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="discord-бот" tabindex="-1">Discord-бот <a class="header-anchor" href="#discord-бот" aria-label="Permalink to &quot;Discord-бот&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Бот — отдельный процесс/контейнер с секцией RimlinkBot. Server.Url указывает HTTPS сервера, ApiToken — отдельный именованный серверный токен с нужными scope. StateFile сохраняет позицию feed, его каталог должен быть постоянным.</p><p>В Discord Developer Portal создай бота, включи необходимый Message Content intent для чат-моста, добавь его в выбранную гильдию с минимальными правами. Задай Discord.Token, GuildId, Language (en/ru), ModeratorRoleIds, AdminRoleIds и id каналов Server/Raids/Market/Moderation/Chat. Нулевые id из примера не являются готовой конфигурацией.</p><p>Для TLS настрой CertificateSha256 (pin) либо доверенную цепочку с CertificateName при необходимости. Проверь чтение статуса, ограничения ролей и публичный чат на тестовом канале, затем включай мост.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Discord.Token и Server.ApiToken — разные секреты. Insecure=false по умолчанию; true только для изолированной сети. Серверные scopes и Discord-роли независимы. Мост пересылает публичный чат, не личные/союзные сообщения. Рестарт/gap требует перечитать состояние, а не выдумывать пропущенные события.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./security-auth">TLS, вход и права</a></li><li><a href="./monitoring">Мониторинг и журнал событий</a></li><li><a href="./../players/chat-pings">Чат, сообщения и пинги</a></li></ul>',10)])])}const m=a(o,[["render",d]]);export{u as __pageData,m as default};
